/* ---------------- 派生工具（由数据计算） ---------------- */
const PEOPLE_MAP = {};
PEOPLE.forEach(p => { PEOPLE_MAP[p.person_id] = p; });
const UNITS_MAP = {};
UNITS.forEach(u => { UNITS_MAP[u.unit_id] = u; });

/* 判断部队在时间点 T 是否存在 */
function unitActiveAt(unit, t) {
  return unit.periods.some(([s, e]) => s <= t && t <= e);
}

/* 取部队在时间点 T 的最新状态（changes 中 date<=T 的最后一条 + 默认值） */
function unitStateAt(unit, t) {
  let state = {
    name: unit.name, level: unit.level, parent_id: unit.parent_id,
    commander: null, political_commissar: null,
    c_title: null, p_title: null, commander_flag: null, pc_flag: null,
    staff: [],
    note: '', event: '', change_date: null,
  };
  for (const c of unit.changes) {
    if (c.date <= t) {
      if (c.name != null) state.name = c.name;
      if (c.parent_id != null) state.parent_id = c.parent_id;
      if (c.commander !== undefined) {
        const changed = c.commander !== state.commander;
        state.commander = c.commander;
        if (c.commander_flag !== undefined) state.commander_flag = c.commander_flag;
        else if (changed) state.commander_flag = null;   // 换人时清除旧标记
      }
      if (c.political_commissar !== undefined) {
        const changed = c.political_commissar !== state.political_commissar;
        state.political_commissar = c.political_commissar;
        if (c.pc_flag !== undefined) state.pc_flag = c.pc_flag;
        else if (changed) state.pc_flag = null;
      }
      if (c.c_title != null) state.c_title = c.c_title;
      if (c.p_title != null) state.p_title = c.p_title;
      if (c.staff !== undefined) state.staff = c.staff;
      if (c.note !== undefined && c.note !== '') state.note = c.note;
      if (c.event !== undefined && c.event !== '') { state.event = c.event; state.change_date = c.date; }
    }
  }
  return state;
}

/* 取某时间点的完整建制快照：返回 { units: Map(uid -> state), roots: [uid], children: Map(uid -> [uid]) } */
function buildSnapshot(t) {
  const units = new Map();
  UNITS.forEach(u => { if (unitActiveAt(u, t)) units.set(u.unit_id, unitStateAt(u, t)); });
  const children = new Map();
  const roots = [];
  units.forEach((st, uid) => {
    const pid = st.parent_id;
    if (pid && units.has(pid)) {
      if (!children.has(pid)) children.set(pid, []);
      children.get(pid).push(uid);
    } else {
      roots.push(uid);
    }
  });
  return { time: t, units, children, roots };
}

/* 某人在时间点 T 的任职单位列表（用于兼任高亮 / 聚焦模式，含机关干部 staff） */
function personUnitsAt(personId, t) {
  const res = [];
  UNITS.forEach(u => {
    if (!unitActiveAt(u, t)) return;
    const st = unitStateAt(u, t);
    if (st.commander === personId || st.political_commissar === personId ||
        (st.staff || []).some(s => s[0] === personId)) res.push(u.unit_id);
  });
  return res;
}

/* 按姓名/别名找人 */
function findPersonByName(q) {
  q = (q || '').trim();
  if (!q) return null;
  return PEOPLE.find(p => p.name === q || (p.alias && p.alias === q)) || null;
}
